-- Rifts World Book 35: Megaverse in Flames, the Dyval Hell weapons and Deevil magic artifacts (printed 130, 136-139)
-- 11 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~348-megaverse-in-flames-dyval-arms-gear.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.
-- Three Hell Energy Weapons (printed 130) and the eight Deevil Magic Artifacts
-- (printed 136-139). Every damage, cost and M.D.C. figure was read off a render
-- of its page. A RANGE IS STORED BY ITS LOW END; cost_note gives the whole range,
-- and for the Soul Stone the wartime price (15-20 million) is stored over the
-- pre-war one, which cost_note keeps. Two headings are plural (Mare Staves, Soul
-- Stones) and the rows are named for one item, as each is priced. The artifacts
-- are category magic. Figures that belong to the user and not the item (the
-- Gargoyle Heart's stone form, the Fire Rage aura) stay in the description and
-- leave ar, sdc and mdc empty; the Mare Staff's own 200 M.D.C. is its mdc.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('hell-pistol', 'Hell Pistol', 'rifts', 'weapon', 8, 30000, '30,000-40,000 credits at places such as the Splynn Dimensional Market and Diablo Island; not sold openly on Earth.', '3D6 M.D. per blast, or 1D8 M.D. as a blade', 1, '500 feet (152 m)', '30 shots, regaining 1 shot per melee round (15 seconds); 300 shots in all before it is spent', 'Each blast is one melee attack', NULL, NULL, NULL, 'Dyval Hell Energy Weapon series. Shaped like a big dagger or knife with a gun barrel running along the middle of its blade, fired by pressing a small stud in place of a trigger, and usable as a dagger in melee. Every Hell weapon is a crude Deevil blend of energy gun and Soulmancy, short-ranged but hard-hitting and needing no upkeep: a soul bound into it powers it from a Soul Crystal, so there are no E-Clips to change. When its total charge is used up the gem inside cracks and the weapon falls to useless scrap within minutes, so the enemy cannot take it.', 'Rifts World Book 35: Megaverse in Flames p.130', NULL),
  ('hell-rifle', 'Hell Rifle', 'rifts', 'weapon', 20, 50000, '50,000-60,000 credits at places such as the Splynn Dimensional Market and Diablo Island; not sold openly on Earth.', '4D6 M.D. per blast, or 2D6 M.D. as a blade', 1, '1,400 feet (427 m)', '30 shots, regaining 1 shot per melee round (15 seconds); 240 shots in all before it is spent', 'Each blast is one melee attack', NULL, NULL, NULL, 'Dyval Hell Energy Weapon series. An energy rifle made as a sword, its barrel down the center between an upper and a lower cutting edge, fired by a stud on the hilt. Every Hell weapon is a crude Deevil blend of energy gun and Soulmancy, short-ranged but hard-hitting and needing no upkeep: a soul bound into it powers it from a Soul Crystal, so there are no E-Clips to change. When its total charge is used up the gem inside cracks and the weapon falls to useless scrap within minutes, so the enemy cannot take it.', 'Rifts World Book 35: Megaverse in Flames p.130', NULL),
  ('hell-cannon', 'Hell Cannon', 'rifts', 'weapon', 40, 65000, '65,000-80,000 credits at places such as the Splynn Dimensional Market and Diablo Island; not sold openly on Earth.', '1D6x10 M.D. per blast, or 4D6 M.D. as a pole arm', 1, '2,000 feet (610 m)', '30 shots, regaining 1 shot per melee round (15 seconds); 120 shots in all before it is spent', 'Each blast is one melee attack', NULL, NULL, NULL, 'Dyval Hell Energy Weapon series, the biggest of the line: a long gun and pole arm in one, the barrel making up most of the shaft and a pole-arm blade fixed at its tip. The book prints its melee damage as 4D6 without a unit; stored as M.D. like the other two. Every Hell weapon is a crude Deevil blend of energy gun and Soulmancy, short-ranged but hard-hitting and needing no upkeep: a soul bound into it powers it from a Soul Crystal, so there are no E-Clips to change. When its total charge is used up the gem inside cracks and the weapon falls to useless scrap within minutes, so the enemy cannot take it.', 'Rifts World Book 35: Megaverse in Flames p.130', NULL),
  ('demon-fly-potion', 'Demon Fly Potion', 'rifts', 'magic', NULL, 250000, '250,000 per potion; rare.', NULL, 0, NULL, 'One 8 ounce (0.23 liter) dose', NULL, NULL, NULL, NULL, 'Deevil magic artifact. A foul-smelling brew of Demon Fly brains that speeds up whoever drinks it, mortal, creature of magic or supernatural. Starting the next melee round and lasting five minutes: Spd doubled, +1 melee attack, +2 initiative, +1 parry, +2 dodge, and dodging no longer costs a melee action. Afterwards the drinker is drained and leaden, with all combat bonuses and attacks halved for another five minutes. Like every Deevil artifact it is rare and seldom found on the open market.', 'Rifts World Book 35: Megaverse in Flames p.137', NULL),
  ('fire-rage-potion', 'Fire Rage Potion', 'rifts', 'magic', NULL, 500000, '500,000 credits per half pint (0.23 liters).', 'Eye fire bolts 2D6 M.D.', 1, 'Fire bolts 30 feet (9.1 m)', 'One half-pint dose', 'Each fire bolt is one attack', NULL, NULL, NULL, 'Deevil magic artifact. The fiery blood of a captured Brek-Shall, drawn from its opened chest while its heart still beats (3D6 pints per demon). A half pint gives the drinker a glowing red aura worth 60 extra M.D.C., immunity to fire (magic fire and M.D. plasma included), +2 to strike, and fire bolts from the eyes for 2D6 M.D. at 30 ft (9.1 m), themselves +2 to strike. It also turns him into a berserker who cannot tell friend from foe, takes offence at anything, shows no mercy, fights to the death, suffers -4 on parry, dodge and pull punch, and has an 01-80% chance of attacking and evading at once. Lasts 1D4 minutes; affects mortals, magic creatures and supernatural beings alike. Rare and seldom on the open market.', 'Rifts World Book 35: Megaverse in Flames p.137', NULL),
  ('gargoyle-heart-amulet', 'Gargoyle Heart Amulet', 'rifts', 'magic', NULL, 3000000, '3 million credits.', 'Punches and kicks +1D6 M.D. with Supernatural Strength, +1D4 M.D. with augmented strength, +2D6 S.D.C. with normal strength', 1, NULL, 'Three uses per 24 hours', NULL, NULL, NULL, NULL, 'Deevil magic artifact. A Gargoyle Lord''s heart, taken still beating and preserved by Necromancy and Soulmancy into a small, withered stone pendant that seems harmless apart from radiating magic. Activated, it gives the wearer the Gargoyle Lord''s Stone Metamorphosis: his body turns to stone worth 200 M.D.C. (in S.D.C. settings, A.R. 17 and 200 S.D.C.) and Supernatural P.S., and hits harder as listed under damage. Lasts 2D6+6 minutes, ending early if the stone form loses all 200 M.D.C.; three uses a day. While active the heart swells back into living, beating flesh. Affects mortals, magic creatures and supernatural beings. Rare and seldom on the open market.', 'Rifts World Book 35: Megaverse in Flames p.137', NULL),
  ('locust-poison', 'Locust Poison', 'rifts', 'magic', NULL, 500000, '500,000 credits for an 8 ounce (0.23 liter) container, enough for 10 weapon coatings or 24 arrows.', 'Paralysis for 2D6 melees and 5D6 damage (M.D. or S.D.C./H.P. by the victim''s nature)', 1, NULL, 'One coating lasts two strikes', NULL, NULL, NULL, NULL, 'Deevil magic artifact. Venom milked from the stinger of a captured Demon Locust, a humiliation a Locust would rather avenge on its tormentors than escape. Smeared on a blade or arrowhead, it works on a hit that draws blood and wipes away after two strikes. A victim who fails a save vs poison of 14 or better is paralyzed for 2D6 melees and takes 5D6 damage, as M.D. against a Mega-Damage being and as S.D.C. and Hit Points otherwise. Affects mortals, magic creatures and supernatural beings; Deevil Assassins enjoy turning it on demons. Rare and seldom on the open market.', 'Rifts World Book 35: Megaverse in Flames p.138', NULL),
  ('maggot-eye-amulet', 'Maggot Eye Amulet', 'rifts', 'magic', NULL, 1500000, '1.5 to 2 million credits.', 'Turns the target to stone for 1D6 melee rounds; save vs magic of 14 or better', 0, '200 feet (61 m)', 'Three beams per day', NULL, NULL, NULL, NULL, 'Deevil magic artifact. A slain Maggot demon''s basketball-sized eye, carried back to Dyval and shrunk by Deevil magic to baseball size, then fixed onto a demon bone with leather or sinew. Three times a day it shoots a yellow beam that petrifies a foe for 1D6 melee rounds, as the Maggot''s own gaze does. Rare and seldom on the open market.', 'Rifts World Book 35: Megaverse in Flames p.138', NULL),
  ('mare-staff', 'Mare Staff', 'rifts', 'magic', NULL, 5000000, '5-10 million credits.', NULL, 1, NULL, 'I.S.P. 3D6+90, regaining 10 an hour', NULL, NULL, NULL, 200, 'Deevil magic artifact, printed under the heading Mare Staves; the rarest of them all because it is so hard to make. A Mare or Nightmare that has outlived its use is blinded, and in a secret Soulmancy rite its head is cut off at the end of the ceremony onto a staff carved with demonic inscriptions, then kept in a sludge so it does not dissolve; six months later the head has shrunk by half and is fused to the wood for good, eyeless but otherwise as in life. The staff keeps the Mare''s psionics at fifth level Mind Melter strength: Bio-Manipulation (10), Empathic Transmission (6), Group Mind Block (22), Hypnotic Suggestion (6), Mind Bolt (10) and Mind Wipe (which costs the staff I.S.P. permanently), and it gives its owner Mind Block Auto-Defense. The staff itself has 200 M.D.C. Rare and seldom on the open market.', 'Rifts World Book 35: Megaverse in Flames p.138-139', NULL),
  ('soul-stone', 'Soul Stone', 'rifts', 'magic', NULL, 15000000, '15-20 million credits each with the Minion War at its height; 5-7 million before the war.', NULL, 0, NULL, 'Holds one soul', NULL, NULL, NULL, NULL, 'Deevil magic artifact, printed under the heading Soul Stones. Gizzard stones cut out of a living Soul Catcher, 2D4 before the wound kills it; no surgery, psionic or magical, gets them out with the demon alive. Polished and carved, each looks like a clear amethyst with drops of blood inside, and the drops form the face of whatever soul it holds. Each is an empty prison for one soul, which needs some other means to put it there: a soul-drinking Rune Weapon with the stone set in it, Soulmancy that treats it as a Soul Crystal, or a pool in the Soul Pits of Grim Mortis, Dyval''s seventh level, where a soul can be called back by its true name. Unlike a made Soul Gem it never wears out and can be reused. Worn at the neck with a few drops of blood on it, it makes the wearer immune to Soul Drink and Rip Soul for as long as it is worn. So rare that even master mages seldom recognise one; the war is only now bringing them into circulation.', 'Rifts World Book 35: Megaverse in Flames p.139', NULL),
  ('succubus-scent', 'Succubus Scent', 'rifts', 'magic', NULL, 200000, '200,000-400,000 credits per one ounce (0.03 liter) container of a dozen applications.', NULL, 0, NULL, 'One ounce, 12 applications', NULL, NULL, NULL, NULL, 'Deevil magic artifact. Pressed from a walnut-sized gland drilled out from between the brain''s hemispheres of a captured, sedated Succubus; one gland gives 8 ounces too strong to use, diluted to 24 ounces in all. One application, rubbed on like perfume, adds 6 to M.A. and 3 to P.B. for four hours; more at once adds nothing. After 13 uses, however far apart, the user''s aura carries a demonic taint: for each use''s four hours and 1D6+1 days after, Psi-Stalkers, Dog Boys and anyone else who can sense such things take him for an evil supernatural being, whatever his alignment, and with continued use the taint stretches to 1D6+1 months and then 1D6+1 years. Nothing hides it. Rare and seldom on the open market.', 'Rifts World Book 35: Megaverse in Flames p.139', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 11 gear rows are in' AS assertion, count(*) AS got, 11 AS want
  FROM gear WHERE slug IN ('hell-pistol', 'hell-rifle', 'hell-cannon', 'demon-fly-potion', 'fire-rage-potion', 'gargoyle-heart-amulet', 'locust-poison', 'maggot-eye-amulet', 'mare-staff', 'soul-stone', 'succubus-scent') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~348-megaverse-in-flames-dyval-arms-gear.sql');
